function validate(input) {
  const [{ Friendship = [], Likes = [] }] = input;
  const pairs = new Set();
  for (const [a, b] of Friendship) {
    if (a === null || b === null) return 'Every friendship needs two users.';
    if (a === b) return `User ${a} cannot be their own friend.`;
    const key = a < b ? `${a}:${b}` : `${b}:${a}`;
    if (pairs.has(key)) return `Users ${a} and ${b} are listed as friends twice.`;
    pairs.add(key);
  }
  const likes = new Set();
  for (const [user, page] of Likes) {
    if (user === null || page === null) return 'Every like needs a user_id and a page_id.';
    const key = `${user}:${page}`;
    if (likes.has(key)) return `User ${user} likes page ${page} twice.`;
    likes.add(key);
  }
  return null;
}

