function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const users = size === 'small' ? 6 : 400;
  const pages = size === 'small' ? [11, 23, 33, 56, 77, 88].slice(0, 2 + pick(5)) : Array.from({ length: 60 }, (_, i) => 100 + i);
  const friendCount = size === 'small' ? pick(9) : 2000;
  const likeCount = size === 'small' ? pick(9) : 2000;
  const Friendship = [], pairs = new Set();
  for (let tries = 0; Friendship.length < friendCount && tries < friendCount * 20 + 50; tries++) {
    const a = 1 + pick(users), b = 1 + pick(users);
    if (a === b) continue;
    const key = a < b ? `${a}:${b}` : `${b}:${a}`;
    if (pairs.has(key)) continue;
    pairs.add(key);
    Friendship.push([a, b]);
  }
  const Likes = [], likes = new Set();
  for (let tries = 0; Likes.length < likeCount && tries < likeCount * 20 + 50; tries++) {
    const user = 1 + pick(users), page = pages[pick(pages.length)];
    const key = `${user}:${page}`;
    if (likes.has(key)) continue;
    likes.add(key);
    Likes.push([user, page]);
  }
  return [{ Friendship, Likes }];
}
